COMMAND.ACTION:
if test -n "${prefix}"; then
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route show_ip_route_rpc.j2 prefix ${prefix} ${__full_line}
elif test -n "${address}"; then
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route show_ip_route_rpc.j2 address ${address} ${__full_line}
elif test -n "${nexthop-group}"; then
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route show_ip_route_rpc.j2 nexthop-group ${__full_line}
elif test -n "${summary}" && test -n "${not-installed}"; then
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route_summary show_ip_route_not_installed_summary_rpc.j2 ${__line}
elif test -n "${summary}"; then
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route_summary show_ip_route_summary_rpc.j2 ${__line}
else
python3 $SONIC_CLI_ROOT/sonic-cli-ip-route-rpc.py show_ip_route show_ip_route_rpc.j2 ${__full_line}
fi
